sys_processor.script:
(function process(g_request, g_response, g_processor) {
	var courseID = g_request.getParameter('sysparm_sys_id');
	// gs.info('** Course agenda ' + courseID);

	//Name all the related lists
	var exporter = new global.ExportWithRelatedLists(x_snc_agenda.Constants.COURSE_TABLE, courseID);
	exporter.addRelatedList(x_snc_agenda.Constants.DAY_TABLE, 'course');
	exporter.addRelatedList(x_snc_agenda.Constants.MODULE_TABLE, 'course');
	exporter.addRelatedList(x_snc_agenda.Constants.NOW_ITEM_TABLE, 'course');

	var m2mModuleList = [];
	var m2mNowItemList = [];
	var verList = [];
	var attList = [];

	//Query for M2M day/modules
	var m2mMod = new GlideRecord(x_snc_agenda.Constants.DAY_MODULE_M2M);
	m2mMod.addQuery('day.course', courseID);
	m2mMod.query();
	while (m2mMod.next()){
		m2mModuleList.push(m2mMod.getUniqueValue());
	}
	//Query for M2M day/now_items
	var m2mItem = new GlideRecord(x_snc_agenda.Constants.DAY_NOW_ITEM_M2M);
	m2mItem.addQuery('day.course', courseID);
	m2mItem.query();
	while (m2mItem.next()){
		m2mNowItemList.push(m2mItem.getUniqueValue());
	}
	//Query for SN versions
	var verGr = new GlideRecord(x_snc_agenda.Constants.VERSION_TABLE);
	verGr.query();
	while (verGr.next()) {
		verList.push(verGr.getUniqueValue());
	}
//Query for Attachments
	// 1. Get sys_ids of days, modules, and Now Items related to this course
	var dayList = [];
	var modList = [];
	var nowItemList = [];

	var dayGr = new GlideRecord(x_snc_agenda.Constants.DAY_TABLE);
	dayGr.addQuery('course', courseID);
	dayGr.query();

	while (dayGr.next()) {
		dayList.push(dayGr.getUniqueValue());
	}

	var nowItemGr = new GlideRecord(x_snc_agenda.Constants.NOW_ITEM_TABLE);
	nowItemGr.addQuery('course', courseID);
	nowItemGr.query();

	while (nowItemGr.next()) {
		nowItemList.push(nowItemGr.getUniqueValue());
	}

	var modGr = new GlideRecord(x_snc_agenda.Constants.MODULE_TABLE);
	modGr.addQuery('course', courseID);
	modGr.query();

	while (modGr.next()) {
		modList.push(modGr.getUniqueValue());
	}

	/*
	gs.info('>>>DEBUG:\n***dayList=\n' + dayList.join('\n') +
		'\n***nowItemList=\n' + nowItemList.join('\n') +
		'\n***modList=\n' + modList.join('\n'));
	*/

	// 2. Build a list of all sys_ids for the attachment records
	var attTargetList = dayList.concat(nowItemList, modList);
	attTargetList.push(courseID);

	// gs.info('>>>DEBUG:\n***attTargetList=\n' + attTargetList.join('\n'));

	// 3. Build the list of attachments to get

	var attList = [];
	var attGr = new GlideRecord('sys_attachment');
	attGr.addQuery('table_sys_id', 'IN', attTargetList.join(','));
	attGr.query();

	while (attGr.next()) {
		attList.push(attGr.getUniqueValue());
	}

	// 4. Build the list of attachment docs to get

	var attDocList = [];
	var attDocGr = new GlideRecord('sys_attachment_doc');
	attDocGr.addQuery('sys_attachment', 'IN', attList.join(','));
	attDocGr.query();

	while (attDocGr.next()) {
		attDocList.push(attDocGr.getUniqueValue());
	}

	// gs.info('>>>DEBUG:\n***attList=' + attList.join('\n') +
	//	'\n***attDocList=' + attDocList.join('\n'));

	exporter.addQuerySet(x_snc_agenda.Constants.DAY_MODULE_M2M, 'sys_idIN' + m2mModuleList.join(','));
	exporter.addQuerySet(x_snc_agenda.Constants.DAY_NOW_ITEM_M2M, 'sys_idIN' + m2mNowItemList.join(','));
	exporter.addQuerySet(x_snc_agenda.Constants.VERSION_TABLE, 'sys_idIN' + verList.join(','));
	exporter.addQuerySet('sys_attachment', 'sys_idIN' + attList.join(','));
	exporter.addQuerySet('sys_attachment_doc', 'sys_idIN' + attDocList.join(','));

	exporter.exportRecords(g_response);

})(g_request, g_response, g_processor);
